python - <<'PY'
import pandas as pd, numpy as np
from pymatgen.core import Structure
D=pd.read_csv('cdft_piezo_pool.csv').set_index('candidate_id')
for id in ['c029','c051','c092','c079','c080']:
 s=Structure.from_str(D.loc[id,'poscar'],fmt='poscar');
 if id=='c092':
  ns=s.get_neighbors(s[0],2.2)
  for i,n in enumerate(ns):
   v=n.coords-s[0].coords
   for m in ns[:i]:
    u=m.coords-s[0].coords
    print(np.rad2deg(np.arccos(np.dot(u,v)/np.linalg.norm(v)/np.linalg.norm(u))))
 if id=='c029':
  vs=[]
  for cl in [i for i,x in enumerate(s) if x.specie.symbol=='Cl']:
   ge=sorted(s.get_neighbors(s[cl],2.5),key=lambda x:x.nn_distance)[0]
   v=s[cl].coords-ge.coords;vs.append(v)
  print(id,vs,np.sum(vs,axis=0))
 if id=='c051':
  vs=[]
  for h in [i for i,x in enumerate(s) if x.specie.symbol=='H']:
   ns=s.get_neighbors(s[h],1.1)
   if ns[0].specie.symbol=='F':vs.append(s[h].coords-ns[0].coords)
  print(id,vs,np.sum(vs,axis=0))
